function ctrl = sht_load_controller_ndot_schedule(ctrl)
%SHT_LOAD_CONTROLLER_NDOT_SCHEDULE Load Ngdot acceleration/deceleration schedule.
% The schedule is generated by Start_CtrlDesign_03_NdotScheduleBoundaryDesign.
% This loader only imports and normalizes the schedule table. The controller
% limiter that consumes NgdotMax/NgdotMin should interpolate this table by Ngc.

if ~isstruct(ctrl) || ~isfield(ctrl, 'ndotSchedule') || isempty(ctrl.ndotSchedule)
    return;
end

ns = ctrl.ndotSchedule;
if ~isfield(ns, 'enable') || ~ns.enable
    return;
end

if local_has_table(ns)
    ctrl.ndotSchedule = local_normalize_table(ns);
    return;
end

sourceFile = local_resolve_source_file(local_get_field(ns, 'sourceFile', ''));
if isempty(sourceFile) || ~exist(sourceFile, 'file')
    error('sht:ndotSchedule:fileNotFound', ...
        'Controller Ngdot schedule file not found: %s', sourceFile);
end

variableName = local_get_field(ns, 'variableName', 'ndotSchedule');
data = load(sourceFile);
if isfield(data, variableName)
    loaded = data.(variableName);
elseif isfield(data, 'ndotSchedule')
    loaded = data.ndotSchedule;
else
    error('sht:ndotSchedule:missingVariable', ...
        'Cannot find variable "%s" in %s.', variableName, sourceFile);
end

loaded.enable = true;
loaded.sourceFile = sourceFile;
loaded.variableName = variableName;
ctrl.ndotSchedule = local_normalize_table(loaded);
end

function tf = local_has_table(ns)
tf = isfield(ns, 'Ngc') && ~isempty(ns.Ngc) ...
    && isfield(ns, 'NgdotMax') && ~isempty(ns.NgdotMax) ...
    && isfield(ns, 'NgdotMin') && ~isempty(ns.NgdotMin) ...
    && isfield(ns, 'AccelWfLimit') && ~isempty(ns.AccelWfLimit) ...
    && isfield(ns, 'DecelWfLimit') && ~isempty(ns.DecelWfLimit);
end

function ns = local_normalize_table(ns)
names = {'Ngc', 'NgdotMax', 'NgdotMin', 'AccelWfLimit', 'DecelWfLimit'};
optionalNames = {'NgcOverDP', 'WfSteady', 'DecelFARTarget', ...
    'DecelWfOverPt3Target'};
for i = 1:numel(names)
    name = names{i};
    ns.(name) = ns.(name)(:);
end
[ngc, order] = sort(ns.Ngc, 'ascend');
ns.Ngc = ngc;
for i = 2:numel(names)
    name = names{i};
    ns.(name) = ns.(name)(order);
end
for i = 1:numel(optionalNames)
    name = optionalNames{i};
    if isfield(ns, name) && numel(ns.(name)) == numel(order)
        ns.(name) = ns.(name)(:);
        ns.(name) = ns.(name)(order);
    end
end
if isfield(ns, 'pointName') && numel(ns.pointName) == numel(order)
    ns.pointName = ns.pointName(order);
end
if isfield(ns, 'pointIndex') && numel(ns.pointIndex) == numel(order)
    ns.pointIndex = ns.pointIndex(order);
end
if isfield(ns, 'accelActiveLimit') && numel(ns.accelActiveLimit) == numel(order)
    ns.accelActiveLimit = ns.accelActiveLimit(order);
end
if isfield(ns, 'decelActiveLimit') && numel(ns.decelActiveLimit) == numel(order)
    ns.decelActiveLimit = ns.decelActiveLimit(order);
end
if isfield(ns, 'detailList') && numel(ns.detailList) == numel(order)
    ns.detailList = ns.detailList(order);
end
ns.enable = local_get_field(ns, 'enable', true);
ns.independentVariable = local_get_field(ns, 'independentVariable', 'Ngc');
ns.interpolationMethod = local_get_field(ns, 'interpolationMethod', 'linear');
ns.extrapolationMode = local_get_field(ns, 'extrapolationMode', 'clamp');
end

function sourceFile = local_resolve_source_file(sourceFile)
if isempty(sourceFile)
    return;
end
if exist(sourceFile, 'file')
    return;
end
sourceFile = fullfile(fileparts(mfilename('fullpath')), sourceFile);
end

function value = local_get_field(s, name, defaultValue)
if isstruct(s) && isfield(s, name) && ~isempty(s.(name))
    value = s.(name);
else
    value = defaultValue;
end
end
